  7 │ import * as fs from "node:fs";
  8 │ import * as os from "node:os";
  9 │ import * as path from "node:path";
 10 │ import { redactSecrets } from "../ui.js";
 11 │ import { ensureGitExclude } from "../core/git_exclude.js";
 12 │ import { identityOf, mkdirVerified } from "../safe_fs.js";
 13 │ import { readWorktreeSettings } from "./config.js";
