 18 │ 
 19 │ export interface WorktreeContext {
 20 │   cwd: string;
 21 │   home: string;
 22 │   readOnly: boolean;
 23 │ }
 24 │ 
 25 │ export interface CommandResult {
 26 │   success: boolean;
 27 │   output: string;
 28 │   data?: unknown;
 29 │ }
