 31 │ export const LIST_SCHEMA = 1;
 32 │ const DEFAULT_LIMIT = 100;
 33 │ const PER_CALL_MS = 5_000;
 34 │ 
 35 │ export class WorktreeError extends Error {
 36 │   constructor(message: string) {
 37 │     super(message);
 38 │     this.name = "WorktreeError";
 39 │   }
 40 │ }
 41 │ 
 42 │ // ---- display and redaction ------------------------------------------------------------------------------------
 43 │ 
 44 │ export function shownBranch(branch: string): string {
 45 │   return redactSecrets(branch);
 46 │ }
 47 │ 
 48 │ export function shownPath(home: string, value: string): string {
 49 │   const normalizedHome = path.resolve(home);
 50 │   const display = value === normalizedHome ? "~" : value.startsWith(normalizedHome + path.sep) ? `~${value.slice(normalizedHome.length)}` : value;
 51 │   return redactSecrets(display);
 52 │ }
 53 │ 
 54 │ // ---- shortcuts and lookup -------------------------------------------------------------------------------------
 55 │ 
 56 │ function loadRegistry(repo: Repo): Registry {
 57 │   return readRegistry(repo.commonDir).registry;
 58 │ }
 59 │ 
 60 │ /** `^` default branch, `@` the branch of the worktree the command runs in, `-` the branch active before the last switch. */
 61 │ export function resolveBranchName(repo: Repo, token: string): string {
 62 │   if (token === "^") {
 63 │     const name = defaultBranch(repo);
 64 │     if (!name) throw new WorktreeError("this repository has no default branch yet");
 65 │     return name;
 66 │   }
 67 │   if (token === "@") {
 68 │     const entry = currentEntry(repo);
 69 │     if (!entry?.branch) throw new WorktreeError("the current worktree is not on a branch");
 70 │     return entry.branch;
 71 │   }
 72 │   if (token === "-") {
 73 │     const previous = loadRegistry(repo).previous;
 74 │     if (!previous) throw new WorktreeError("there is no previous worktree recorded");
 75 │     return previous;
 76 │   }
 77 │   const problem = validateBranchName(token);
 78 │   if (problem) throw new WorktreeError(`invalid branch name: ${problem}`);
 79 │   return token;
 80 │ }
 81 │ 
 82 │ function looksLikePath(token: string): boolean {
 83 │   return path.isAbsolute(token) || token === "." || token === ".." || token.startsWith("./") || token.startsWith("../") || token.startsWith("~");
 84 │ }
 85 │ 
 86 │ /** A branch (or shortcut) or a worktree path, resolved to a Git-listed worktree. */
 87 │ export function findEntry(repo: Repo, token: string, home: string): WorktreeEntry {
 88 │   if (looksLikePath(token)) {
 89 │     const expanded = token.startsWith("~") ? path.join(home, token.slice(1)) : path.resolve(repo.cwd, token);
 90 │     let real: string;
 91 │     try { real = fs.realpathSync(expanded); } catch { throw new WorktreeError(`no worktree at ${shownPath(home, expanded)}`); }
 92 │     const hit = repo.entries.find((entry) => { try { return fs.realpathSync(entry.path) === real; } catch { return false; } });
 93 │     if (!hit) throw new WorktreeError(`${shownPath(home, real)} is not a worktree of this repository`);
 94 │     return hit;
 95 │   }
 96 │   const name = resolveBranchName(repo, token);
 97 │   const hit = repo.entries.find((entry) => entry.branch === name);
 98 │   if (!hit) throw new WorktreeError(`no worktree for branch ${shownBranch(name)}`);
 99 │   return hit;
100 │ }
101 │ 
102 │ function kindOf(repo: Repo, entry: WorktreeEntry, registry: Registry): "main" | "task" | "named" | "external" {
103 │   if (entry.isMain) return "main";
104 │   const taskBase = path.join(repo.repoPath, ".nexus", "worktrees") + path.sep;
105 │   if (entry.branch?.startsWith("nexus/") && entry.path.startsWith(taskBase)) return "task";
106 │   return registry.worktrees.some((item) => item.path === entry.path) ? "named" : "external";
107 │ }
108 │ 
109 │ // ---- measurements ---------------------------------------------------------------------------------------------
110 │ 
111 │ export interface Dirty { staged: number; modified: number; untracked: number; conflicted: number; ignored: number; total: number }
112 │ 
113 │ /** One `git status --porcelain=v2 -z` call. `ignored` counts ignored paths only when asked (removal safety). */
114 │ export function statusOf(dir: string, options: { ignored?: boolean } = {}): Dirty {
115 │   const args = ["status", "--porcelain=v2", "-z", options.ignored ? "--untracked-files=all" : "--untracked-files=normal"];
116 │   if (options.ignored) args.push("--ignored=matching");
117 │   const out = git(dir, args, { timeoutMs: PER_CALL_MS }).stdout;
118 │   const dirty: Dirty = { staged: 0, modified: 0, untracked: 0, conflicted: 0, ignored: 0, total: 0 };
119 │   const records = out.split("\0");
120 │   for (let i = 0; i < records.length; i++) {
121 │     const record = records[i];
122 │     if (!record) continue;
123 │     const kind = record[0];
124 │     if (kind === "1" || kind === "2") {
125 │       if (record[2] !== ".") dirty.staged++;
126 │       if (record[3] !== ".") dirty.modified++;
127 │       if (kind === "2") i++; // the original path of a rename follows as its own record
128 │     } else if (kind === "u") dirty.conflicted++;
129 │     else if (kind === "?") dirty.untracked++;
130 │     else if (kind === "!") {
131 │       const file = record.slice(2);
132 │       if (file === ".nexus/" || file.startsWith(".nexus/")) continue; // Nexus's own state is not user data
133 │       dirty.ignored++;
134 │     }
135 │   }
136 │   dirty.total = dirty.staged + dirty.modified + dirty.untracked + dirty.conflicted;
137 │   return dirty;
138 │ }
139 │ 
140 │ export type IntegratedReason = "same-commit" | "ancestor" | "empty-diff" | "same-tree" | "patch-id";
141 │ 
142 │ /** Whether `head` adds nothing to `target` (both commit ids). Cheap checks first; each call is time-bounded. */
143 │ export function integratedReason(repo: Repo, head: string, target: string): IntegratedReason | null {
144 │   if (head === target) return "same-commit";
145 │   const at = (args: string[]) => git(repo.cwd, args, { allowFailure: true, timeoutMs: PER_CALL_MS });
146 │   if (at(["merge-base", "--is-ancestor", head, target]).status === 0) return "ancestor";
147 │   if (at(["diff", "--no-ext-diff", "--no-textconv", "--quiet", `${target}...${head}`]).status === 0) return "empty-diff";
148 │   const trees = (ref: string) => at(["rev-parse", "--verify", "--quiet", "--end-of-options", `${ref}^{tree}`]).stdout.trim();
149 │   const headTree = trees(head);
150 │   if (headTree && headTree === trees(target)) return "same-tree";
151 │   const cherry = at(["cherry", target, head]);
152 │   const lines = cherry.stdout.split("\n").filter(Boolean);
153 │   if (cherry.status === 0 && lines.length > 0 && lines.every((line) => line.startsWith("-"))) return "patch-id";
154 │   return null;
155 │ }
156 │ 
157 │ // ---- switch ---------------------------------------------------------------------------------------------------
158 │ 
159 │ export interface SwitchOptions { create?: boolean; base?: string }
160 │ 
161 │ function ownerOf(repo: Repo): string {
162 │   const url = git(repo.cwd, ["config", "--get", "remote.origin.url"], { allowFailure: true }).stdout.trim();
163 │   const match = url.match(/[:/]([^/:]+)\/[^/]+?(?:\.git)?$/);
164 │   return sanitizeBranch(match?.[1] ?? "local");
165 │ }
166 │ 
167 │ export function switchWorktree(ctx: WorktreeContext, branchToken: string, options: SwitchOptions = {}): CommandResult {
168 │   const repo = openRepo(ctx.cwd);
169 │   const registry = loadRegistry(repo);
170 │   const name = resolveBranchName(repo, branchToken);
171 │   const existing = repo.entries.find((entry) => entry.branch === name);
172 │   const here = currentEntry(repo);
173 │   if (existing) {
174 │     if (options.create) throw new WorktreeError(`branch ${shownBranch(name)} already has a worktree; drop -c to switch to it`);
175 │     rememberPrevious(repo, here?.branch, name);
176 │     return { success: true, output: `Worktree for ${shownBranch(name)} is at ${shownPath(ctx.home, existing.path)}`, data: { branch: name, path: existing.path, created: false } };
177 │   }
178 │ 
179 │   const branchExists = refExists(repo, `refs/heads/${name}`);
180 │   if (options.create && branchExists) throw new WorktreeError(`branch ${shownBranch(name)} already exists; use switch without -c to check it out`);
181 │   if (!options.create && !branchExists) throw new WorktreeError(`branch ${shownBranch(name)} does not exist; use -c to create it`);
182 │ 
183 │   let baseName = "";
184 │   let baseSha = "";
185 │   if (options.create) {
186 │     baseName = options.base ? resolveBranchName(repo, options.base) : (defaultBranch(repo) ?? "HEAD");
187 │     const sha = resolveCommit(repo, baseName);
188 │     if (!sha) throw new WorktreeError(`base ${shownBranch(baseName)} does not name a commit`);
189 │     baseSha = sha;
190 │   }
191 │ 
192 │   const settings = readWorktreeSettings(ctx.home);
193 │   const resolved = resolveWorktreePath({
194 │     repoPath: repo.repoPath, repo: repo.repoName, owner: ownerOf(repo), branch: name,
195 │     layout: settings.layout, template: settings.pathTemplate, allowOutside: settings.allowOutside,
196 │   });
197 │   const target = resolved.path;
198 │   if (identityOf(target)) throw new WorktreeError(`${shownPath(ctx.home, target)} already exists; refusing to reuse it (another branch may sanitise to the same name)`);
199 │   if (repo.entries.some((entry) => entry.path === target)) throw new WorktreeError(`${shownPath(ctx.home, target)} is already a worktree`);
200 │ 
201 │   // Parent directories are created one verified component at a time, so a linked `.nexus/worktrees` is refused.
202 │   const parent = path.dirname(target);
203 │   if (settings.layout === "nexus" && !settings.allowOutside) {
204 │     ensureGitExclude(repo.repoPath);
205 │     mkdirVerified(repo.repoPath, parent);
206 │   } else if (!identityOf(parent)) {
207 │     fs.mkdirSync(parent, { recursive: true, mode: 0o700 });
208 │   }
209 │ 
210 │   const args = options.create
211 │     ? ["worktree", "add", "-b", name, "--end-of-options", target, baseSha]
212 │     : ["worktree", "add", "--end-of-options", target, name];
213 │   git(repo.cwd, args);
214 │ 
215 │   const root = allowedRoot(repo.repoPath, settings.layout);
216 │   if (!settings.allowOutside) {
217 │     const real = fs.realpathSync(target);
218 │     const realRoot = fs.realpathSync(root);
219 │     if (real !== path.join(realRoot, path.relative(root, target))) {
220 │       throw new WorktreeError("the new worktree resolved outside its allowed directory; inspect it with `git worktree list` before using it");
221 │     }
222 │   }
223 │ 
224 │   updateRegistry(repo.commonDir, (reg) => {
225 │     reg.worktrees = reg.worktrees.filter((item) => item.path !== target && item.branch !== name);
226 │     reg.worktrees.push({ branch: name, path: target, base: options.create ? baseName : name, createdAt: new Date().toISOString() });
227 │     if (here?.branch && here.branch !== name) reg.previous = here.branch;
228 │   });
229 │   return { success: true, output: `Created worktree for ${shownBranch(name)} at ${shownPath(ctx.home, target)}`, data: { branch: name, path: target, created: true } };
230 │ }
231 │ 
232 │ function rememberPrevious(repo: Repo, from: string | null | undefined, to: string): void {
233 │   if (!from || from === to) return;
234 │   try { updateRegistry(repo.commonDir, (reg) => { reg.previous = from; }); } catch { /* the shortcut is a convenience */ }
235 │ }
236 │ 
237 │ // ---- path -----------------------------------------------------------------------------------------------------
238 │ 
239 │ export function pathOf(ctx: WorktreeContext, token: string): CommandResult {
240 │   const repo = openRepo(ctx.cwd);
241 │   const entry = findEntry(repo, token, ctx.home);
242 │   return { success: true, output: entry.path, data: { path: entry.path, branch: entry.branch } };
243 │ }
244 │ 
245 │ // ---- list -----------------------------------------------------------------------------------------------------
246 │ 
247 │ export interface ListItem {
248 │   branch: string | null;
249 │   path: string;
250 │   head: string;
251 │   main: boolean;
252 │   current: boolean;
253 │   detached: boolean;
254 │   locked: boolean;
255 │   prunable: boolean;
256 │   kind: "main" | "task" | "named" | "external";
257 │   registered: boolean;
258 │   dirty: Dirty | null;
259 │   ahead: number | null;
260 │   behind: number | null;
261 │   integrated: IntegratedReason | null;
262 │   ageSeconds: number | null;
263 │   /** Reserved for the activity marker (WP-1314). */
264 │   agent: null;
265 │   error?: string;
266 │ }
267 │ 
268 │ export function listWorktrees(ctx: WorktreeContext, options: { limit?: number; json?: boolean } = {}): CommandResult {
269 │   const repo = openRepo(ctx.cwd);
270 │   const { registry, warning } = readRegistry(repo.commonDir);
271 │   const here = currentEntry(repo);
272 │   const limit = Math.max(1, options.limit ?? DEFAULT_LIMIT);
273 │   const target = defaultBranch(repo);
274 │   const targetSha = target ? resolveCommit(repo, target) : undefined;
275 │ 
276 │   const rank = (entry: WorktreeEntry) => (entry.isMain ? 0 : entry === here ? 1 : registry.worktrees.some((r) => r.path === entry.path) ? 2 : 3);
277 │   const ordered = [...repo.entries].sort((a, b) => rank(a) - rank(b));
278 │   const shown = ordered.slice(0, limit);
279 │ 
280 │   const now = Date.now() / 1000;
281 │   const items: ListItem[] = shown.map((entry) => {
282 │     const item: ListItem = {
283 │       branch: entry.branch ? shownBranch(entry.branch) : null, path: entry.path, head: entry.head, main: entry.isMain, current: entry === here,
284 │       detached: entry.detached, locked: entry.locked, prunable: entry.prunable, kind: kindOf(repo, entry, registry),
285 │       registered: registry.worktrees.some((r) => r.path === entry.path), dirty: null, ahead: null, behind: null,
286 │       integrated: null, ageSeconds: null, agent: null,
287 │     };
288 │     if (entry.prunable) { item.error = "directory is missing"; return item; }
289 │     try {
290 │       item.dirty = statusOf(entry.path);
291 │       if (targetSha && entry.head) {
292 │         const counts = gitOut(repo.cwd, ["rev-list", "--left-right", "--count", "--end-of-options", `${targetSha}...${entry.head}`], { timeoutMs: PER_CALL_MS }).split(/\s+/);
293 │         item.behind = Number(counts[0]);
294 │         item.ahead = Number(counts[1]);
295 │         item.integrated = integratedReason(repo, entry.head, targetSha);
296 │       }
297 │       const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: PER_CALL_MS }));
298 │       if (Number.isFinite(stamp)) item.ageSeconds = Math.max(0, Math.round(now - stamp));
299 │     } catch (err) {
300 │       item.error = (err as Error).message.slice(0, 120);
301 │     }
302 │     return item;
303 │   });
304 │ 
305 │   const data = {
306 │     schema: LIST_SCHEMA,
307 │     repo: { name: repo.repoName, path: repo.repoPath },
308 │     defaultBranch: target ? shownBranch(target) : null,
309 │     total: repo.entries.length,
310 │     truncated: repo.entries.length > shown.length,
311 │     ...(warning ? { warning } : {}),
312 │     items,
313 │   };
314 │   if (options.json) return { success: true, output: JSON.stringify(data), data };
315 │ 
316 │   const lines = items.map((item) => {
317 │     const mark = item.current ? "@" : item.main ? "^" : " ";
318 │     const dirty = item.dirty ? (item.dirty.total ? `+${item.dirty.staged} ~${item.dirty.modified} ?${item.dirty.untracked}${item.dirty.conflicted ? ` !${item.dirty.conflicted}` : ""}` : "clean") : "?";
319 │     const track = item.ahead === null ? "" : `↑${item.ahead}↓${item.behind}`;
320 │     const state = item.integrated ? `integrated(${item.integrated})` : "";
321 │     const age = item.ageSeconds === null ? "" : humanAge(item.ageSeconds);
322 │     return [mark, item.branch ?? "(detached)", item.kind, dirty, track, state, age, shownPath(ctx.home, item.path), item.error ? `[${item.error}]` : ""].filter((part, i) => i < 2 || part !== "").join("  ");
323 │   });
324 │   if (data.truncated) lines.push(`... ${repo.entries.length - shown.length} more worktrees not shown (--limit ${repo.entries.length} to show all)`);
325 │   if (warning) lines.push(`warning: ${warning}`);
326 │   return { success: true, output: lines.join("\n"), data };
327 │ }
328 │ 
329 │ function humanAge(seconds: number): string {
330 │   if (seconds < 3600) return `${Math.max(1, Math.round(seconds / 60))}m`;
331 │   if (seconds < 86400) return `${Math.round(seconds / 3600)}h`;
332 │   return `${Math.round(seconds / 86400)}d`;
333 │ }
334 │ 
335 │ // ---- remove ---------------------------------------------------------------------------------------------------
336 │ 
337 │ export interface RemoveOptions { force?: boolean; deleteUnmerged?: boolean }
338 │ 
339 │ export function removeWorktrees(ctx: WorktreeContext, tokens: string[], options: RemoveOptions = {}): CommandResult {
340 │   if (tokens.length === 0) throw new WorktreeError("usage: worktree remove <branch|path>... [--force] [--delete-unmerged]");
341 │   const lines: string[] = [];
342 │   let success = true;
343 │   for (const token of tokens) {
344 │     try {
345 │       lines.push(removeOne(ctx, token, options));
346 │     } catch (err) {
347 │       success = false;
348 │       lines.push(`${shownBranch(token)}: ${redactSecrets((err as Error).message)}`);
349 │     }
350 │   }
351 │   return { success, output: lines.join("\n") };
352 │ }
353 │ 
354 │ /** Removes one worktree (and its branch) after the safety checks; returns a one-line report or throws. */
355 │ export function removeOne(ctx: WorktreeContext, token: string, options: RemoveOptions): string {
356 │   const repo = openRepo(ctx.cwd);
357 │   const registry = loadRegistry(repo);
358 │   const entry = findEntry(repo, token, ctx.home);
359 │   const label = entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path);
360 │   if (entry.isMain) throw new WorktreeError("the main worktree cannot be removed");
361 │   if (currentEntry(repo) === entry) throw new WorktreeError("you are inside this worktree; run the command from another directory");
362 │   if (entry.locked) throw new WorktreeError("the worktree is locked; unlock it with `git worktree unlock` first");
363 │   if (kindOf(repo, entry, registry) === "task" && !options.force) {
364 │     throw new WorktreeError("this worktree belongs to a speculative run (/worktree discard); use --force to remove it anyway");
365 │   }
366 │ 
367 │   const dropFromRegistry = () => updateRegistry(repo.commonDir, (reg) => { reg.worktrees = reg.worktrees.filter((item) => item.path !== entry.path); });
368 │   const target = defaultBranch(repo);
369 │   const targetSha = target ? resolveCommit(repo, target) : undefined;
370 │   const integrated = entry.head && targetSha ? integratedReason(repo, entry.head, targetSha) : null;
371 │   if (!integrated && !options.deleteUnmerged) {
372 │     throw new WorktreeError(`${entry.branch ? "branch" : "HEAD"} is not merged into ${target ? shownBranch(target) : "the default branch"}; merge it, or pass --delete-unmerged to discard its commits`);
373 │   }
374 │ 
375 │   if (entry.prunable) {
376 │     git(repo.cwd, ["worktree", "prune"]);
377 │   } else {
378 │     const before = verifiedWorktreeDir(repo, entry);
379 │     if (!options.force) {
380 │       const dirty = statusOf(entry.path, { ignored: true });
381 │       if (dirty.total + dirty.ignored > 0) {
382 │         throw new WorktreeError(`worktree has ${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked and ${dirty.ignored} ignored path(s); commit or clean them, or pass --force`);
383 │       }
384 │     }
385 │     // The directory must still be the one that was inspected: a swap for a link or another tree is refused.
386 │     const after = identityOf(entry.path);
387 │     if (!after || after.dev !== before.dev || after.ino !== before.ino) throw new WorktreeError("the worktree directory changed while it was being checked; nothing was removed");
388 │     git(repo.cwd, ["worktree", "remove", ...(options.force ? ["--force"] : []), "--end-of-options", entry.path]);
389 │   }
390 │ 
391 │   let branchNote = "";
392 │   if (entry.branch && entry.branch !== target) {
393 │     const stillCheckedOut = listAfter(repo).some((other) => other.branch === entry.branch);
394 │     if (!stillCheckedOut) {
395 │       git(repo.cwd, ["branch", "-D", "--end-of-options", entry.branch]);
396 │       branchNote = " and deleted its branch";
397 │     }
398 │   }
399 │   dropFromRegistry();
400 │   return `Removed worktree ${label}${branchNote}`;
401 │ }
402 │ 
403 │ function listAfter(repo: Repo): WorktreeEntry[] {
404 │   return openRepo(repo.cwd).entries;
405 │ }
406 │ 
407 │ /** The worktree directory must be a real directory (not a link) whose `.git` file points into this repository. */
408 │ function verifiedWorktreeDir(repo: Repo, entry: WorktreeEntry): { dev: number; ino: number } {
409 │   const before = identityOf(entry.path);
410 │   const stat = fs.lstatSync(entry.path);
411 │   if (!before || stat.isSymbolicLink() || !stat.isDirectory()) throw new WorktreeError("the worktree path is not a plain directory; refusing to remove it");
412 │   const dotGit = path.join(entry.path, ".git");
413 │   const dotStat = fs.lstatSync(dotGit);
414 │   if (!dotStat.isFile()) throw new WorktreeError("the worktree has no .git file; refusing to remove it");
415 │   const pointer = fs.readFileSync(dotGit, "utf8").trim();
416 │   const expected = `gitdir: ${path.join(repo.commonDir, "worktrees")}${path.sep}`;
417 │   if (!pointer.startsWith(expected)) throw new WorktreeError("the worktree does not belong to this repository's common directory; refusing to remove it");
418 │   return { dev: before.dev, ino: before.ino };
419 │ }
420 │ 
421 │ export function homeDir(): string {
422 │   return process.env.HOME || os.homedir();
423 │ }

