335 │ // ---- remove ---------------------------------------------------------------------------------------------------
336 │ 
337 │ export interface RemoveOptions { force?: boolean; deleteUnmerged?: boolean }
338 │ 
339 │ export function removeWorktrees(ctx: WorktreeContext, tokens: string[], options: RemoveOptions = {}): CommandResult {
340 │   if (tokens.length === 0) throw new WorktreeError("usage: worktree remove <branch|path>... [--force] [--delete-unmerged]");
341 │   const lines: string[] = [];
342 │   let success = true;
343 │   for (const token of tokens) {
344 │     try {
345 │       lines.push(removeOne(ctx, token, options));
346 │     } catch (err) {
347 │       success = false;
348 │       lines.push(`${shownBranch(token)}: ${redactSecrets((err as Error).message)}`);
349 │     }
350 │   }
351 │   return { success, output: lines.join("\n") };
352 │ }
353 │ 
354 │ /** Removes one worktree (and its branch) after the safety checks; returns a one-line report or throws. */
355 │ export function removeOne(ctx: WorktreeContext, token: string, options: RemoveOptions): string {
356 │   const repo = openRepo(ctx.cwd);
357 │   const registry = loadRegistry(repo);
358 │   const entry = findEntry(repo, token, ctx.home);
359 │   const label = entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path);
360 │   if (entry.isMain) throw new WorktreeError("the main worktree cannot be removed");
361 │   if (currentEntry(repo) === entry) throw new WorktreeError("you are inside this worktree; run the command from another directory");
362 │   if (entry.locked) throw new WorktreeError("the worktree is locked; unlock it with `git worktree unlock` first");
363 │   if (kindOf(repo, entry, registry) === "task" && !options.force) {
364 │     throw new WorktreeError("this worktree belongs to a speculative run (/worktree discard); use --force to remove it anyway");
365 │   }
366 │ 
367 │   const dropFromRegistry = () => updateRegistry(repo.commonDir, (reg) => { reg.worktrees = reg.worktrees.filter((item) => item.path !== entry.path); });
368 │   const target = defaultBranch(repo);
369 │   const targetSha = target ? resolveCommit(repo, target) : undefined;
370 │   const integrated = entry.head && targetSha ? integratedReason(repo, entry.head, targetSha) : null;
371 │   if (!integrated && !options.deleteUnmerged) {
372 │     throw new WorktreeError(`${entry.branch ? "branch" : "HEAD"} is not merged into ${target ? shownBranch(target) : "the default branch"}; merge it, or pass --delete-unmerged to discard its commits`);
373 │   }
374 │ 
375 │   if (entry.prunable) {
376 │     git(repo.cwd, ["worktree", "prune"]);
377 │   } else {
378 │     const before = verifiedWorktreeDir(repo, entry);
379 │     if (!options.force) {
380 │       const dirty = statusOf(entry.path, { ignored: true });
381 │       if (dirty.total + dirty.ignored > 0) {
382 │         throw new WorktreeError(`worktree has ${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked and ${dirty.ignored} ignored path(s); commit or clean them, or pass --force`);
383 │       }
384 │     }
385 │     // The directory must still be the one that was inspected: a swap for a link or another tree is refused.
386 │     const after = identityOf(entry.path);
387 │     if (!after || after.dev !== before.dev || after.ino !== before.ino) throw new WorktreeError("the worktree directory changed while it was being checked; nothing was removed");
388 │     git(repo.cwd, ["worktree", "remove", ...(options.force ? ["--force"] : []), "--end-of-options", entry.path]);
389 │   }
390 │ 
391 │   let branchNote = "";
392 │   if (entry.branch && entry.branch !== target) {
393 │     const stillCheckedOut = listAfter(repo).some((other) => other.branch === entry.branch);
394 │     if (!stillCheckedOut) {
395 │       git(repo.cwd, ["branch", "-D", "--end-of-options", entry.branch]);
396 │       branchNote = " and deleted its branch";
397 │     }
398 │   }
399 │   dropFromRegistry();
400 │   return `Removed worktree ${label}${branchNote}`;
401 │ }
402 │ 
403 │ function listAfter(repo: Repo): WorktreeEntry[] {
404 │   return openRepo(repo.cwd).entries;
405 │ }
406 │ 
407 │ /** The worktree directory must be a real directory (not a link) whose `.git` file points into this repository. */
408 │ function verifiedWorktreeDir(repo: Repo, entry: WorktreeEntry): { dev: number; ino: number } {
409 │   const before = identityOf(entry.path);
410 │   const stat = fs.lstatSync(entry.path);
411 │   if (!before || stat.isSymbolicLink() || !stat.isDirectory()) throw new WorktreeError("the worktree path is not a plain directory; refusing to remove it");
412 │   const dotGit = path.join(entry.path, ".git");
413 │   const dotStat = fs.lstatSync(dotGit);
414 │   if (!dotStat.isFile()) throw new WorktreeError("the worktree has no .git file; refusing to remove it");
415 │   const pointer = fs.readFileSync(dotGit, "utf8").trim();
416 │   const expected = `gitdir: ${path.join(repo.commonDir, "worktrees")}${path.sep}`;
417 │   if (!pointer.startsWith(expected)) throw new WorktreeError("the worktree does not belong to this repository's common directory; refusing to remove it");
418 │   return { dev: before.dev, ino: before.ino };
419 │ }
420 │ 
421 │ export function homeDir(): string {
422 │   return process.env.HOME || os.homedir();
423 │ }
